import * as THREE from 'three';
import { describe, expect, it } from 'vitest';
import { ParticleManager } from './ParticleManager';

function positions(manager: ParticleManager): Float32Array {
  return manager.points.geometry.getAttribute('position').array as Float32Array;
}

describe('ParticleManager', () => {
  it('attaches one reusable Points draw object to the scene', () => {
    const scene = new THREE.Scene();
    const manager = new ParticleManager({ scene, capacity: 3 });

    expect(scene.children).toContain(manager.points);
    expect(manager.points.geometry.getAttribute('position').count).toBe(3);
    expect(manager.points.material.vertexColors).toBe(true);
    manager.dispose();
    expect(scene.children).not.toContain(manager.points);
  });

  it('updates particle motion, gravity and colour fade in preallocated buffers', () => {
    const manager = new ParticleManager({ capacity: 2, gravity: -10 });
    const positionBuffer = positions(manager);
    expect(manager.emit({
      position: { x: 1, y: 2, z: 3 },
      velocity: { x: 4, y: 5, z: 6 },
      color: { r: 1, g: 0.5, b: 0.25 },
      lifetime: 2,
    })).toBe(1);

    manager.update(0.1);
    expect(positions(manager)).toBe(positionBuffer);
    expect(Array.from(positionBuffer.slice(0, 3))).toEqual([1.399999976158142, 2.4000000953674316, 3.5999999046325684]);
    const colour = manager.points.geometry.getAttribute('color').array as Float32Array;
    expect(Array.from(colour.slice(0, 3))).toEqual([0.949999988079071, 0.4749999940395355, 0.23749999701976776]);
  });

  it('releases expired particles back into the fixed pool', () => {
    const manager = new ParticleManager({ capacity: 2, gravity: 0 });
    manager.emit({ position: { x: 0, y: 0, z: 0 }, lifetime: 0.05 });
    manager.emit({ position: { x: 1, y: 0, z: 0 }, lifetime: 0.05 });
    expect(manager.emit({ position: { x: 2, y: 0, z: 0 } })).toBe(0);

    manager.update(0.05);
    expect(manager.activeCount).toBe(0);
    expect(manager.availableCount).toBe(2);
    expect(manager.emit({ position: { x: 2, y: 0, z: 0 }, count: 3 })).toBe(2);
    expect(manager.activeCount).toBe(2);
  });

  it('clears active particles and becomes inert after disposal', () => {
    const manager = new ParticleManager({ capacity: 2 });
    manager.emit({ position: { x: 0, y: 0, z: 0 }, count: 2 });
    manager.clear();
    expect(manager.activeCount).toBe(0);
    expect(manager.availableCount).toBe(2);
    manager.dispose();
    expect(manager.emit({ position: { x: 0, y: 0, z: 0 } })).toBe(0);
  });
});
